create or replace function stroked_alerts.matches(s stroked_alerts.subscriptions,p jsonb) returns boolean language sql immutable set search_path='' as $$select (s.regions ? 'All Canada' or s.regions ? (case lower(trim(p->>'province')) when 'prince edward island' then 'PEI' when 'pei' then 'PEI' else p->>'province' end)) and exists(select 1 from jsonb_array_elements_text(coalesce(p->'categories','[]')) c where s.categories ? c)$$;
